    keyissues:{name:"Summarise the key issues",re:/key (issues?|findings?|drivers?)|the main (issues?|problems?|drivers?)|so far (we|i) (have|know)|to recap/i,q:"Before recommending, what are the two or three key issues you found?"},
    nextsteps:{name:"Outline next steps and impact",re:/next steps?|then (we|i) would|roll ?out|implement|in the first (30|60|90)|pilot|expected (impact|result)/i,q:"What happens next, and what impact do you expect?"},
