  function mb32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
  function mkR(seed){const f=mb32(seed);return {i:(a,b)=>a+Math.floor(f()*(b-a+1)),p:arr=>arr[Math.floor(f()*arr.length)]}}
  Object.keys(GEN).forEach(k=>{let tot=0;GEN[k].forEach(tp=>{tp.keys=Object.keys(tp.s);tp.n=tp.keys.reduce((m,x)=>m*tp.s[x].length,1);tp.off=tot;tot+=tp.n});GEN[k].total=tot});
  function genAt(k,n){const g=GEN[k];let tp=g[0];for(const x of g){if(n>=x.off&&n<x.off+x.n){tp=x;break}}
    let m=n-tp.off;const v={};tp.keys.forEach(key=>{const arr=tp.s[key],val=arr[m%arr.length];m=Math.floor(m/arr.length);v[key]=val;if(Array.isArray(val))val.forEach((x,j)=>v[key+j]=x)});
    let p=typeof tp.t==="function"?tp.t(v):tp.t.replace(/\{(\w+)\}/g,(_,x)=>v[x]!==undefined?v[x]:"");
    p=p.replace(/\b([Aa]) (?=[aeioAEIO])/g,"$1n ");p=p.charAt(0).toUpperCase()+p.slice(1);
    return {p,f:tp.f?tp.f(v,mkR((Math.imul(n+1,2654435761)>>>0)||1)):{},id:"#"+(PFX[k]||"P")+"-"+n.toString(36).toUpperCase()}}
